  $("axisChart").innerHTML = values.map(([label,count])=>'<div class="bar-row"><span class="bar-label" title="' + escapeHtml(label) + '">' + escapeHtml(label) + '</span><div class="bar-track"><div class="bar-fill" style="width:' + (count/max*100) + '%"></div></div><strong>' + count + '</strong></div>').join("") || '<div class="empty">Sem dados para o filtro atual.</div>';
